using System;
using System.Collections.Generic;
using System.Collections.Specialized;
using System.Drawing;
using System.IO;
using System.Threading;
using System.Windows.Forms;
using PcKvm;
class WindowsClipboardTest {
 class Host:Form { public void Recreate(){RecreateHandle();} }
 static void Check(bool okay,string name){if(!okay)throw new Exception(name);Console.WriteLine("PASS "+name);}
 static void Pump(){Application.DoEvents();Application.DoEvents();}
 static ClipboardSnapshot Item(ClipboardKind kind,string name,string mime,byte[] bytes){return new ClipboardSnapshot{Kind=kind,Items=new List<ClipboardItem>{new ClipboardItem{Name=name,Mime=mime,Length=bytes.Length,Open=delegate{return new MemoryStream(bytes,false);}}}};}
 static void Publish(WindowsClipboard adapter,ClipboardSnapshot snapshot){for(int n=0;;n++){try{adapter.Publish(snapshot);return;}catch(System.Runtime.InteropServices.ExternalException){if(n==19)throw;Pump();Thread.Sleep(10);}}}
 static ClipboardSnapshot Capture(WindowsClipboard adapter){for(int n=0;;n++){try{return adapter.Capture();}catch(System.Runtime.InteropServices.ExternalException){if(n==19)throw;Pump();Thread.Sleep(10);}}}
 static byte[] Bytes(ClipboardItem item){using(Stream s=item.Open())using(MemoryStream o=new MemoryStream()){s.CopyTo(o);return o.ToArray();}}
 static DataObject Backup(List<IDisposable> held){IDataObject source=Clipboard.GetDataObject();DataObject copy=new DataObject();if(source==null)return copy;foreach(string format in source.GetFormats(false)){object value=source.GetData(format,false);Stream stream=value as Stream;Image image=value as Image;if(stream!=null){MemoryStream cached=new MemoryStream();if(stream.CanSeek)stream.Position=0;stream.CopyTo(cached);cached.Position=0;held.Add(cached);value=cached;}else if(image!=null){value=new Bitmap(image);held.Add((IDisposable)value);}if(value!=null)copy.SetData(format,false,value);}return copy;}
 [STAThread]static int Main(){string root=Path.Combine(Path.GetTempPath(),"pckvm-clipboard-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);List<IDisposable>held=new List<IDisposable>();DataObject original=null;
 try{original=Backup(held);using(Host host=new Host()){IntPtr handle=host.Handle;int changes=0;using(WindowsClipboard adapter=new WindowsClipboard(host,root,delegate{changes++;})){
 string exact="PC-KVM TEST \u4e2d\u6587 \ud83d\ude3a\r\n\n  ";Clipboard.SetText(exact,TextDataFormat.UnicodeText);Pump();ClipboardSnapshot text=Capture(adapter);Check(text.Kind==ClipboardKind.Text&&ClipboardWire.TextContent(text)==exact,"captures exact Unicode text");Check(changes>0&&adapter.Revision>0,"native update reaches owning STA");
 int before=changes;long revision=adapter.Revision;Publish(adapter,ClipboardWire.Text(exact+"remote"));Pump();Check(Clipboard.GetText(TextDataFormat.UnicodeText)==exact+"remote","publishes exact Unicode text");Check(adapter.IsKnownSequence(adapter.Sequence)&&changes==before&&adapter.Revision==revision,"publication does not echo");
 DataObject unsupported=new DataObject();unsupported.SetData("PC-KVM-unsupported-test",false,"marker");Clipboard.SetDataObject(unsupported,true);Pump();Check(Capture(adapter)==null&&adapter.Revision>revision&&changes>before,"unsupported update advances revision");host.Recreate();Clipboard.SetText("PC-KVM TEST recreate");Pump();Check(changes>before+1,"listener survives handle recreation");
 byte[] png;using(Bitmap bitmap=new Bitmap(3,2))using(MemoryStream data=new MemoryStream()){bitmap.SetPixel(1,1,Color.Red);bitmap.Save(data,System.Drawing.Imaging.ImageFormat.Png);png=data.ToArray();}Publish(adapter,Item(ClipboardKind.Image,"image.png","image/png",png));Pump();IDataObject published=Clipboard.GetDataObject();Check(published.GetDataPresent("PNG",false)&&published.GetDataPresent(DataFormats.Bitmap),"publishes PNG and bitmap");ClipboardSnapshot image=Capture(adapter);Check(image.Kind==ClipboardKind.Image&&Bytes(image.Items[0]).Length==png.Length,"captures original PNG");using(MemoryStream wire=new MemoryStream())ClipboardWire.Write(wire,image,null);Check(image.Id>0,"captured image has transferable identity");
 byte[] jpeg;using(Bitmap photo=new Bitmap(3,3))using(MemoryStream encoded=new MemoryStream()){photo.Save(encoded,System.Drawing.Imaging.ImageFormat.Jpeg);jpeg=encoded.ToArray();}Publish(adapter,Item(ClipboardKind.Image,"photo.jpg","image/jpeg",jpeg));Pump();using(Stream encoded=Clipboard.GetDataObject().GetData("PNG",false) as Stream)using(Image decoded=Image.FromStream(encoded))Check(decoded.RawFormat.Guid==System.Drawing.Imaging.ImageFormat.Png.Guid,"JPEG image is normalized to real PNG clipboard bytes"); using(Bitmap onlyBitmap=new Bitmap(2,4)){onlyBitmap.SetPixel(0,0,Color.Blue);Clipboard.SetImage(onlyBitmap);}Pump();ClipboardSnapshot bitmapCapture=Capture(adapter);using(MemoryStream encoded=new MemoryStream(Bytes(bitmapCapture.Items[0])))using(Image decoded=Image.FromStream(encoded))Check(decoded.Width==2&&decoded.Height==4,"captures native bitmap as PNG");adapter.Release(bitmapCapture); string source=Path.Combine(root,"source-test.bin");File.WriteAllBytes(source,new byte[]{1,4,9,16});DataObject mixed=new DataObject();mixed.SetData(DataFormats.FileDrop,new string[]{source});mixed.SetData(DataFormats.UnicodeText,"PC-KVM fallback must not win");Clipboard.SetDataObject(mixed,true);Pump();ClipboardSnapshot files=Capture(adapter);Check(files.Kind==ClipboardKind.Files&&files.Items.Count==1,"file drop takes priority over text");Check(Bytes(files.Items[0]).Length==4,"captures file stream without loading into memory");using(MemoryStream wire=new MemoryStream())ClipboardWire.Write(wire,files,null);Check(files.Id>0,"captured files have transferable identity");Publish(adapter,files);Pump();StringCollection paths=Clipboard.GetFileDropList();Check(paths.Count==1&&File.Exists(paths[0])&&File.ReadAllBytes(paths[0]).Length==4,"publishes real paths as FileDropList");Check(!Clipboard.ContainsText(),"file publication never converts paths to text");File.WriteAllBytes(source,new byte[]{99});bool invalid=false;try{Bytes(files.Items[0]);}catch(IOException){invalid=true;}Check(invalid,"changed file source is rejected");
 string duplicateDir=Path.Combine(root,"duplicate");Directory.CreateDirectory(duplicateDir);string duplicate=Path.Combine(duplicateDir,Path.GetFileName(source));File.WriteAllBytes(duplicate,new byte[]{7});DataObject duplicateDrop=new DataObject();duplicateDrop.SetData(DataFormats.FileDrop,new string[]{source,duplicate});Clipboard.SetDataObject(duplicateDrop,true);Pump();ClipboardSnapshot pair=Capture(adapter);using(MemoryStream wire=new MemoryStream())ClipboardWire.Write(wire,pair,null);Check(pair.Items.Count==2&&pair.Items[0].Name!=pair.Items[1].Name,"same-named files remain transferable"); Publish(adapter,ClipboardWire.Text("PC-KVM TEST preserve invalid"));invalid=false;try{Publish(adapter,Item(ClipboardKind.Image,"bad.png","image/png",new byte[]{1,2,3}));}catch(Exception){invalid=true;}Check(invalid&&Clipboard.GetText()=="PC-KVM TEST preserve invalid","invalid image leaves clipboard unchanged");ClipboardSnapshot large=Item(ClipboardKind.Image,"big.png","image/png",png);large.Items[0].Length=64L*1024*1024+1;invalid=false;try{Publish(adapter,large);}catch(Exception){invalid=true;}Check(invalid&&Clipboard.GetText()=="PC-KVM TEST preserve invalid","image bound checked before publish");
 bool wrong=false;Thread thread=new Thread(delegate(){try{Capture(adapter);}catch(InvalidOperationException){wrong=true;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();Check(wrong,"foreign STA rejected");string imageCache=image.Items[0].Path;adapter.Release(image);Check(!File.Exists(imageCache),"release removes captured image cache");
 }int stopped=changes;Clipboard.SetText("PC-KVM TEST disposed");Pump();Check(changes==stopped,"disposing detaches listener");}return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}finally{try{if(original!=null)Clipboard.SetDataObject(original,true);}finally{foreach(IDisposable resource in held)resource.Dispose();if(Directory.Exists(root))Directory.Delete(root,true);}}}
}